function time12(t){if(!t)return '联系确认';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300);}
function capture(){const r=state.route;r.scroll=$('.page-scroll')?.scrollTop||$('.message-list')?.scrollTop||0;}
function nav(view,args={},replace=false){capture();state.modal=null;state.errors={};if(!replace){state.stack.push({...state.route,args:{...state.route.args}});history.pushState({abPrototype:true},'',location.pathname+location.search+'#'+view);}state.route={view,args};render();}
function back(){if(state.route.view==='code')state.forms.code=null;state.modal=null;state.errors={};if(state.stack.length&&history.state?.abPrototype){history.back();return;}state.route=state.stack.pop()||{view:'home',args:{}};render();}
function requireLogin(next){if(!state.logged){beginAuth(next);return false;}return true;}
function header(title,extra=''){return `<div class="page-head">${ib('back','back','返回')}<h1>${esc(title)}</h1>${extra||'<span class="spacer"></span>'}</div>`;}
function page(title,body,extra='',soft=false){return `<div class="root-content"><div class="page-scroll ${soft?'soft':''}">${header(title,extra)}${body}</div></div>`;}
function avatar(id){const p=getDriver(id);return `<div class="avatar ${id==='me'?'blue':''}">${esc((p?.name||'司').slice(0,1))}</div>`;}
function person(id,sub='',action='driver'){const d=getDriver(id);return `<div class="person-row">${avatar(id)}<div class="person-main"><b>${esc(d?.name||'已注销用户')}</b><p>${esc(sub||d?.carrier||'')}</p></div>${action?ib(action,'chevron','查看司机',`data-id="${esc(id)}"`):''}</div>`;}
function empty(title,sub='',action='',label=''){return `<div class="empty"><div class="empty-icon">${I('box')}</div><h3>${esc(title)}</h3>${sub?`<p>${esc(sub)}</p>`:''}${action?btn(action,esc(label),'button secondary'):''}</div>`;}
function row(label,value){return `<div class="detail-row"><span>${esc(label)}</span><span>${esc(value)}</span></div>`;}
function menu(label,sub,action,icon='chevron',attrs=''){return `<button class="list-button" data-action="${action}" ${attrs}><div class="list-main"><div class="list-title">${esc(label)}</div>${sub?`<div class="list-sub">${esc(sub)}</div>`:''}</div>${I(icon)}</button>`;}
function field(form,key,label,type='text',options={}){const f=state.forms[form]||{},e=state.errors[key];let control;if(options.choices){control=`<select data-field="${key}" data-form-key="${form}" name="${key}" aria-label="${esc(label)}" ${options.required?'required':''}>${options.choices.map(c=>{const [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(f[key]??'')===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;}else if(type==='textarea'){control=`<textarea data-field="${key}" data-form-key="${form}" name="${key}" aria-label="${esc(label)}" placeholder="${esc(options.placeholder||'')}" maxlength="${options.max||1000}">${esc(f[key]||'')}</textarea>`;}else{control=`<input data-field="${key}" data-form-key="${form}" name="${key}" aria-label="${esc(label)}" type="${type}" value="${esc(f[key]??'')}" placeholder="${esc(options.placeholder||'')}" ${type==='number'?`min="${options.min??0}" step="${options.step||1}"`:''} ${options.max?`maxlength="${options.max}"`:''} ${options.disabled?'disabled':''} ${type==='tel'?'autocomplete="tel"':''}>`;}
return `<label class="field ${e?'invalid':''}"><span class="field-label">${esc(label)}${options.optional?'<span class="optional">选填</span>':''}</span>${control}${e?`<span class="field-error" role="alert">${esc(e)}</span>`:''}</label>`;}
function formError(){return state.errors._?`<div class="form-error" role="alert">${esc(state.errors._)}</div>`:'';}
function submit(label){return `<div class="form-submit"><button class="button" type="submit">${esc(label)}</button></div>`;}
function check(form,key,label){return `<label class="check-row"><input type="checkbox" name="${key}" data-field="${key}" data-form-key="${form}" ${state.forms[form]?.[key]?'checked':''}><span>${esc(label)}</span></label>`;}
function bottomNav(active){return `<nav class="bottom-nav" aria-label="主导航">${[['home','home','首页'],['circle','users','司机圈'],['me','user','我的']].map(([id,ic,l])=>`<button data-action="root" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${I(ic)}<span>${l}</span></button>`).join('')}</nav>`;}
function mapSVG(){const selected=state.apt==='a2'?2:state.apt==='a3'?3:1;return `<svg viewBox="0 0 390 660" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="390" height="660" fill="#e9ecee"/><path d="M290 90h100v120l-55 20-45-30Z" fill="#dce7dd"/><path d="M-60 400 450 210M-60 230 450 40M-10 600 450 425M80-30 320 700M-70 10 170 700M270-20 510 680" fill="none" stroke="#fff" stroke-width="19"/><path d="M-60 400 450 210M-60 230 450 40M-10 600 450 425M80-30 320 700M-70 10 170 700M270-20 510 680" fill="none" stroke="#d5d9dc" stroke-width="1"/>${[[145,264,70,48,1],[243,202,53,45,2],[84,376,62,49,3],[38,177,40,40,0],[210,371,53,70,0],[308,316,50,54,0],[27,280,57,38,0],[245,106,44,42,0],[149,110,43,53,0],[140,466,66,44,0],[303,470,47,59,0]].map(([x,y,w,h,id])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" transform="rotate(-20 ${x+w/2} ${y+h/2})" class="map-building ${selected===id&&state.homeView==='apartments'?'selected':''}"/>`).join('')}<text x="160" y="235" transform="rotate(-20 160 235)" class="map-label">W Pine Ave</text><text x="286" y="346" transform="rotate(70 286 346)" class="map-label">S Grove St</text><text x="27" y="111" class="map-label">KOREATOWN</text><text x="320" y="170" class="map-label">PARK</text><text x="30" y="484" class="map-label">W 8th St</text></svg>`;}
